import { useState, useEffect } from "react";
import {
  MagnifyingGlassIcon,
  ClockIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import AdminSidebar from "../AdminSidebar";
import { getAllReports, updateReportStatus, notifyUser } from "../../../services/api";

const ReportDetailModal = ({ report, isOpen, onClose, onResolve }) => {
  if (!isOpen || !report) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl max-w-2xl w-full">
        <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 flex items-center justify-between rounded-t-2xl">
          <h3 className="text-xl font-bold text-white">Report Details</h3>
          <button
            onClick={onClose}
            className="text-white hover:bg-white/20 p-2 rounded-lg transition-colors"
          >
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>

        <div className="p-6 space-y-6">
          <div className="grid grid-cols-2 gap-6">
            <div>
              <h4 className="font-medium text-gray-700 mb-2">Reporter</h4>
              <p className="font-semibold text-gray-900">{report.reporter_name}</p>
              <p className="text-sm text-gray-500">ID: {report.reporter_id}</p>
            </div>
            <div>
              <h4 className="font-medium text-gray-700 mb-2">Reported User</h4>
              <p className="font-semibold text-gray-900">{report.reported_user_name}</p>
              <p className="text-sm text-gray-500">ID: {report.reported_user_id}</p>
            </div>
          </div>

          <div>
            <h4 className="font-medium text-gray-700 mb-2">Report Reason</h4>
            <p className="text-gray-900">{report.reason}</p>
          </div>

          {report.description && (
            <div>
              <h4 className="font-medium text-gray-700 mb-2">Description</h4>
              <p className="text-gray-900">{report.description}</p>
            </div>
          )}

          <div>
            <h4 className="font-medium text-gray-700 mb-2">Submitted Date</h4>
            <p className="text-gray-900">{new Date(report.created_at).toLocaleString()}</p>
          </div>

          {report.status === 'pending' && (
            <div className="flex gap-3 pt-4 border-t">
              <button
                onClick={() => onResolve(report.id, 'warning')}
                className="flex-1 bg-yellow-500 text-white py-2.5 rounded-lg hover:bg-yellow-600 transition-colors font-medium"
              >
                Issue Warning
              </button>
              <button
                onClick={() => onResolve(report.id, 'suspended')}
                className="flex-1 bg-red-500 text-white py-2.5 rounded-lg hover:bg-red-600 transition-colors font-medium"
              >
                Suspend User
              </button>
              <button
                onClick={() => onResolve(report.id, 'invalid')}
                className="flex-1 bg-gray-500 text-white py-2.5 rounded-lg hover:bg-gray-600 transition-colors font-medium"
              >
                Mark Invalid
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default function UserReports() {
  const [selectedReport, setSelectedReport] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [reports, setReports] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    resolved: 0,
    thisWeek: 0
  });

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      setIsLoading(true);
      const response = await getAllReports();
      setReports(response);

      const pending = response.filter(r => r.status === 'pending' || !r.status).length;
      const resolved = response.filter(r => r.status !== 'pending' && r.status).length;
      const oneWeekAgo = new Date();
      oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
      const thisWeek = response.filter(r => new Date(r.created_at) > oneWeekAgo).length;

      setStats({
        total: response.length,
        pending,
        resolved,
        thisWeek
      });
    } catch (error) {
      console.error('Error fetching reports:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleViewDetails = (report) => {
    setSelectedReport(report);
    setShowDetailModal(true);
  };

  const handleResolveReport = async (reportId, resolution) => {
    try {
      await updateReportStatus(reportId, { status: resolution });
      setShowDetailModal(false);
      setSelectedReport(null);
      await fetchReports();
    } catch (error) {
      console.error('Error resolving report:', error);
      alert('Failed to resolve report');
    }
  };

  const getStatusBadgeClass = (status) => {
    switch(status) {
      case 'pending':
        return 'bg-yellow-100 text-yellow-600';
      case 'resolved':
        return 'bg-green-100 text-green-600';
      case 'suspended':
        return 'bg-red-100 text-red-600';
      case 'invalid':
        return 'bg-gray-100 text-gray-600';
      case 'warning':
        return 'bg-orange-100 text-orange-600';
      default:
        return 'bg-gray-100 text-gray-600';
    }
  };

  const filteredReports = reports.filter(report =>
    (report.reported_user_name?.toLowerCase().includes(search.toLowerCase()) ||
    report.reporter_name?.toLowerCase().includes(search.toLowerCase()) ||
    report.reason?.toLowerCase().includes(search.toLowerCase())) &&
    (showHistory ? report.status !== 'pending' && report.status : report.status === 'pending' || !report.status)
  );

  return (
    <div className="flex h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Sidebar */}
      <AdminSidebar />

      {/* Main Content */}
      <div className="flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-white border-b shadow-sm">
          <div className="flex items-center justify-between px-8 py-6">
            <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              User Reports
            </h2>
            <div className="w-10 h-10 bg-gradient-to-r from-blue-500 to-indigo-500 rounded-full flex items-center justify-center text-white font-semibold">
              AS
            </div>
          </div>
        </div>

        <div className="p-8 overflow-y-auto h-[calc(100vh-5rem)]">
          {/* Stats */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
              <p className="text-gray-500 text-sm mt-1">Total Reports</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
              <p className="text-gray-500 text-sm mt-1">Pending</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-green-600">{stats.resolved}</p>
              <p className="text-gray-500 text-sm mt-1">Resolved</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-blue-600">{stats.thisWeek}</p>
              <p className="text-gray-500 text-sm mt-1">This Week</p>
            </div>
          </div>

          {/* Filter & Search */}
          <div className="flex justify-between items-center mb-6">
            <div className="relative w-64">
              <MagnifyingGlassIcon className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search reports..."
                className="pl-10 pr-3 py-2 w-full border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:outline-none"
              />
            </div>
            <button
              onClick={() => setShowHistory(!showHistory)}
              className={`flex items-center px-4 py-2 rounded-lg transition-colors ${
                showHistory
                  ? 'bg-blue-100 text-blue-600'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <ClockIcon className="w-5 h-5 mr-2" />
              {showHistory ? 'Pending' : 'History'}
            </button>
          </div>

          {/* Reports Table */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
            {isLoading ? (
              <div className="p-8 text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                <p className="text-gray-500 mt-2">Loading reports...</p>
              </div>
            ) : filteredReports.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                No reports found
              </div>
            ) : (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-left border-b text-gray-500 bg-gray-50">
                        <th className="px-6 py-3">Reported User</th>
                        <th className="px-6 py-3">Reporter</th>
                        <th className="px-6 py-3">Reason</th>
                        <th className="px-6 py-3">Date</th>
                        <th className="px-6 py-3">Status</th>
                        <th className="px-6 py-3">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {filteredReports.map((report) => (
                        <tr key={report.id} className="hover:bg-gray-50">
                          <td className="px-6 py-3">
                            <p className="font-medium text-gray-900">{report.reported_user_name}</p>
                            <p className="text-xs text-gray-500">ID: {report.reported_user_id}</p>
                          </td>
                          <td className="px-6 py-3">
                            <p className="font-medium text-gray-900">{report.reporter_name}</p>
                            <p className="text-xs text-gray-500">ID: {report.reporter_id}</p>
                          </td>
                          <td className="px-6 py-3">
                            <p>{report.reason}</p>
                          </td>
                          <td className="px-6 py-3">
                            {new Date(report.created_at).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-3">
                            <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusBadgeClass(report.status)}`}>
                              {report.status || 'pending'}
                            </span>
                          </td>
                          <td className="px-6 py-3">
                            <button
                              onClick={() => handleViewDetails(report)}
                              className="text-blue-600 hover:text-blue-700 font-medium text-sm"
                            >
                              View Details
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Pagination */}
                <div className="flex justify-between items-center p-6 border-t bg-gray-50">
                  <p className="text-sm text-gray-500">
                    Showing 1 to {filteredReports.length} of {reports.length} results
                  </p>
                  <div className="flex space-x-2">
                    <button className="p-2 border rounded-lg hover:bg-gray-200">
                      <ChevronLeftIcon className="h-5 w-5" />
                    </button>
                    <button className="px-3 py-1 border rounded-lg bg-blue-600 text-white">1</button>
                    <button className="px-3 py-1 border rounded-lg hover:bg-gray-200">2</button>
                    <button className="p-2 border rounded-lg hover:bg-gray-200">
                      <ChevronRightIcon className="h-5 w-5" />
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Report Detail Modal */}
      <ReportDetailModal
        report={selectedReport}
        isOpen={showDetailModal}
        onClose={() => setShowDetailModal(false)}
        onResolve={handleResolveReport}
      />
    </div>
  );
}
